'use client';
import { useState } from 'react';
import { useAuth } from '@/context/AuthContext';
import { Power, ShoppingBag, DollarSign, Star } from 'lucide-react';

export default function DashboardPage() {
    const { user } = useAuth();
    const [isOpen, setIsOpen] = useState(true);

    return (
        <div className="p-4 space-y-6">
            <header className="flex justify-between items-center">
                <div>
                    <h1 className="text-xl font-bold text-gray-900">Biryani Palace</h1>
                    <p className="text-sm text-green-600 font-medium flex items-center gap-1">
                        <span className="w-2 h-2 bg-green-500 rounded-full"></span>
                        Open for orders
                    </p>
                </div>
                <button
                    onClick={() => setIsOpen(!isOpen)}
                    className={`px-4 py-2 rounded-full font-bold text-sm flex items-center gap-2 transition-all ${isOpen ? 'bg-green-500 text-white shadow-lg shadow-green-200' : 'bg-red-500 text-white shadow-lg shadow-red-200'
                        }`}
                >
                    <Power size={16} />
                    {isOpen ? 'OPEN' : 'CLOSED'}
                </button>
            </header>

            {/* Stats Cards */}
            <div className="grid grid-cols-2 gap-4">
                <div className="bg-orange-50 p-4 rounded-xl border border-orange-100">
                    <div className="flex items-center gap-2 mb-2 text-orange-600">
                        <ShoppingBag size={18} />
                        <span className="text-xs font-bold uppercase">Orders</span>
                    </div>
                    <p className="text-2xl font-bold text-gray-900">24</p>
                    <p className="text-xs text-green-600 font-medium mt-1">↑ 12% today</p>
                </div>

                <div className="bg-green-50 p-4 rounded-xl border border-green-100">
                    <div className="flex items-center gap-2 mb-2 text-green-600">
                        <DollarSign size={18} />
                        <span className="text-xs font-bold uppercase">Revenue</span>
                    </div>
                    <p className="text-2xl font-bold text-gray-900">₹4,250</p>
                    <p className="text-xs text-green-600 font-medium mt-1">↑ 8% today</p>
                </div>
            </div>

            {/* Live Orders Widget */}
            <div className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden">
                <div className="p-4 border-b border-gray-100 flex justify-between items-center">
                    <h3 className="font-bold text-gray-900">Live Orders</h3>
                    <span className="bg-primary/10 text-primary px-2 py-1 rounded text-xs font-bold">3 Active</span>
                </div>
                <div className="divide-y divide-gray-50">
                    {[1, 2, 3].map((i) => (
                        <div key={i} className="p-4 flex justify-between items-center hover:bg-gray-50">
                            <div>
                                <p className="font-bold text-gray-900">Order #882{i}</p>
                                <p className="text-xs text-gray-500">2 items • ₹350</p>
                            </div>
                            <span className="text-xs font-medium bg-yellow-100 text-yellow-700 px-2 py-1 rounded">
                                Cooking
                            </span>
                        </div>
                    ))}
                </div>
            </div>

            {/* Rating Card */}
            <div className="bg-purple-50 p-4 rounded-xl border border-purple-100 flex items-center justify-between">
                <div>
                    <p className="text-purple-900 font-bold">Restaurant Rating</p>
                    <p className="text-xs text-purple-700 mt-1">Based on last 50 reviews</p>
                </div>
                <div className="flex items-center gap-1 bg-white px-3 py-1.5 rounded-lg shadow-sm">
                    <Star size={16} className="text-yellow-400 fill-yellow-400" />
                    <span className="font-bold text-gray-900">4.5</span>
                </div>
            </div>
        </div>
    );
}
